import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parsePlaylist, codecFromInit, PREFETCH, bufferTarget, nextPollAction, MAX_EMPTY, needsNewInit } from './feed-mse';

// Fixtures GENERATED by the real server functions (scripts/feed-fixtures.mjs) from a real fMP4 with
// the recorder movflags: init.bin = ftyp+moov up to the first moof (777 B measured),
// playlist.txt = 8 fragments of 1 s (real byte-ranges), playlist-multi.txt = 2 chunks of 2
// fragments with #EXT-X-DISCONTINUITY between them. Read through `process.cwd()` = pattern of the
// tooltips-icons guard test.
const FIX = join(process.cwd(), 'src/features/archive/services/__fixtures__');
const read = (n: string) => join(FIX, n);
const BASE = 'http://127.0.0.1:7101/api/v1/play/p_rec/playlist.m3u8?token=tk%2Fte&janela=120&ts=1792339200';

describe('parsePlaylist (spec 4.1)', () => {
  const p = parsePlaylist(readFileSync(read('playlist.txt'), 'utf8'), BASE);

  it('reads the init with byte-range and resolves the relative URI against the playlist URL', () => {
    expect(p.initUrl).toBe('http://127.0.0.1:7101/api/v1/play/p_rec/14.mp4/file?token=tk%2Fte');
    expect(p.initEnd).toBe(777);
  });

  it('reads the 8 fragments with duration and byte-range, in order', () => {
    expect(p.frags.length).toBe(8);
    expect(p.frags[0]).toEqual({
      url: 'http://127.0.0.1:7101/api/v1/play/p_rec/14.mp4/file?token=tk%2Fte',
      dur: 1, ini: 777, size: 204,
    });
    expect(p.frags[1].ini).toBe(39786);
    expect(p.frags.every((f) => f.dur === 1 && f.size === 204)).toBe(true);
  });

  it('recognizes VOD and ENDLIST', () => {
    expect(p.vod).toBe(true);
    expect(p.end).toBe(true);
  });

  it('the MULTI playlist (hour turn) becomes ONE list in order, with no discontinuity mark (rev.2)', () => {
    const m = parsePlaylist(readFileSync(read('playlist-multi.txt'), 'utf8'),
      'http://127.0.0.1:7101/api/v1/play/p_rec/playlist.m3u8');
    expect(m.frags.length).toBe(4);                       // 2 chunks x 2 fragments, a single list
    expect(m.frags[2].url).toContain('/transcode/102');   // the new chunk already comes in the frag URL
    expect(m.initUrl).toContain('/transcode/100');        // EXT-X-MAP of the first chunk
  });
});

describe('codecFromInit (spec 4.2)', () => {
  it('extracts the exact codec string from the real recorder init', () => {
    expect(codecFromInit(new Uint8Array(readFileSync(read('init.bin'))))).toEqual(['avc1.f4001e']);
  });

  it('bytes without a recognizable stsd return an empty list', () => {
    expect(codecFromInit(new Uint8Array([0, 0, 0, 8, 0x66, 0x66, 0x74, 0x79, 1, 2, 3, 4]))).toEqual([]);
  });
});

it('PREFETCH is the 30 s buffer of the spec', () => {
  expect(PREFETCH).toBe(30);
});

// spec 2026-10-20 (playback edge, D2): the poll decision when the playlist brought
// nothing new. Plan amendment E1: the outputs are 'retry' | 'end' ('stop' was the Cause 2 defect).
describe('nextPollAction (spec borda, D2)', () => {
  it('live sem fragmento novo: sempre retry (a playlist é a única fonte de verdade)', () => {
    expect(nextPollAction({ live: true, fresh: 0, empty: 0 })).toBe('retry');
    expect(nextPollAction({ live: true, fresh: 0, empty: 9 })).toBe('retry');
  });
  it('VOD sem fragmento novo: retry até MAX_EMPTY, depois end', () => {
    expect(nextPollAction({ live: false, fresh: 0, empty: MAX_EMPTY - 1 })).toBe('retry');
    expect(nextPollAction({ live: false, fresh: 0, empty: MAX_EMPTY })).toBe('end');
    expect(nextPollAction({ live: false, fresh: 0, empty: MAX_EMPTY + 4 })).toBe('end');
  });
  it('com fragmento novo: retry', () => {
    expect(nextPollAction({ live: false, fresh: 2, empty: 9 })).toBe('retry');
  });
});

// 2026-10-19 "30 s of clock" amendment: the slack in seconds of MEDIA follows the playbackRate.
it('the buffer target follows the speed: 30 s of clock, 240 s of media cap', () => {
  expect(bufferTarget(1)).toBe(30);
  expect(bufferTarget(2)).toBe(60);
  expect(bufferTarget(4)).toBe(120);
  expect(bufferTarget(8)).toBe(240);
  expect(bufferTarget(16)).toBe(240);          // cap
  expect(bufferTarget(0.5)).toBe(30);          // never below 1x
  expect(bufferTarget(0)).toBe(30);            // invalid/absent rate treated as 1x
});

// spec 2026-10-21 (4.5): a playlist that turns to another file brings a different init
describe('needsNewInit', () => {
  const pl = (name: string, ts = '1792339200') => parsePlaylist(
    `#EXT-X-MAP:URI="${name}/file",BYTERANGE="777@0"\n#EXTINF:1,\n${name}/file\n`,
    BASE.replace('ts=1792339200', `ts=${ts}`));
  it('mudou de arquivo, mudou o init; só o ts do mesmo arquivo não', () => {
    const s1 = pl('15.mp4');
    expect(needsNewInit(s1.initUrl, s1)).toBe(false);
    // only the ts changed -> init continues
    expect(needsNewInit(s1.initUrl, pl('15.mp4', '1792339260'))).toBe(false);
    // the new session has another init
    expect(needsNewInit(s1.initUrl, pl('15-s1.mp4'))).toBe(true);
    // without init there is nothing to fetch
    expect(needsNewInit(s1.initUrl, { ...s1, initUrl: '' })).toBe(false);
  });
});
